INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b9ae19a9-26a3-478b-a150-03f77564bfc0', '21feff02-016d-46e2-bb9d-c27495133b1b', '111. óra: Projektóra', 'Épülettervezés I. - Vetületi képek megrajzolása, makett alaprajzának elkészítése.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "f26758b3-a0d3-488c-b9db-cf4754fd7fd8", "text": "Mit mutat meg egy épület felülnézete (alaprajza)?", "type": "multiple-choice", "options": [{"id": "b1082400-63bf-4776-883d-165117d79776", "text": "Az épület felülről látható elrendezését és méreteit", "isCorrect": true}, {"id": "433cfd2b-ff74-4fc8-bec7-8664163af58c", "text": "A tető színét", "isCorrect": false}, {"id": "1315e5d0-30ed-49f6-8d9f-6bd4adea8e7f", "text": "Az épület magasságát", "isCorrect": false}, {"id": "ebbafe39-cd9e-437d-9120-6008608dbec3", "text": "Az ablakok mintáját", "isCorrect": false}], "timeLimit": 15}, {"id": "758a8cd0-8acc-47d5-a54e-c2b86070eb88", "text": "Egy épület makettjének elkészítése segít a térbeli arányok megértésében.", "type": "true-false", "options": [{"id": "871020fe-e5de-4765-820c-7bc9110d4dd2", "text": "Igaz", "isCorrect": true}, {"id": "956539de-818a-4fa8-a177-c7977cb77e41", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c9510184-fc9e-4e3a-9343-929549a73534", "text": "Hány m² az 5 m x 6 m-es alaprajzú házalap területe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "17c07822-86fa-48b2-9441-380e2577c8fd", "text": "A méretarányos rajz készítése elengedhetetlen az építészetben.", "type": "true-false", "options": [{"id": "3d0d1f1f-8add-426f-9514-99f6ccc8f3f3", "text": "Igaz", "isCorrect": true}, {"id": "e9fc48cd-f11a-4a3b-8d50-d78041027336", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "dca464ed-3244-42c9-babe-373aafd948b7", "text": "Ha az 1:100 méretarányú rajzon a fal 5 cm, hány méter a valóságban? (5 * 100 cm)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "3d7a0ecb-d716-4c57-8dde-98590baf57ca", "text": "A csoportszervezés és munkamegosztás felgyorsítja a projekt elvégzését.", "type": "true-false", "options": [{"id": "09a15322-b8a6-456d-a766-c476e1bdf4c0", "text": "Igaz", "isCorrect": true}, {"id": "f01eeff2-74d8-4260-b0e4-de8f50c233b6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b30b993c-8c5d-4362-970b-c71f904fd51a", "text": "Hány oldallapja van a téglatest alakú épületnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e157b224-e599-4f8d-9c8d-aef55f962067', '21feff02-016d-46e2-bb9d-c27495133b1b', '112. óra: Projektóra II.', 'Épülettervezés II. - Makett megépítése kartonból, legóból, egységkockákból.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "f9e68249-79ea-417e-80c5-8ab565a0f788", "text": "Hány darab 1 cm³-es kiskockára van szükség egy 3 cm x 4 cm x 5 cm-es épületmakett megépítéséhez?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "0252685c-6011-440f-a8c3-ab967f2c4193", "text": "Az épületmakett térfogata megegyezik a felhasznált egységkockák térfogatának összegevel.", "type": "true-false", "options": [{"id": "28c5f7e7-e451-4ed9-b2ce-e1f79687b62d", "text": "Igaz", "isCorrect": true}, {"id": "9ff6a733-54f0-4f0d-a410-c011d061b56b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2f93f79f-2e8f-4975-930f-e3eaf9f34c82", "text": "Melyik testből építhető fel a legkönnyebben téglatest alakú ház?", "type": "multiple-choice", "options": [{"id": "8a02a797-2519-416e-8bc9-fdb89a5d2e81", "text": "Egységkockákból / kartondobozból", "isCorrect": true}, {"id": "be7f2309-72e1-4efb-8967-9c6d50e35afc", "text": "Gömbökből", "isCorrect": false}, {"id": "6f3b5a9c-8b96-41f6-bb65-3eadd9bcb51b", "text": "Kúpokból", "isCorrect": false}, {"id": "e351b022-656e-4daa-ad72-2be5776dd0af", "text": "Hengerekből", "isCorrect": false}], "timeLimit": 15}, {"id": "718b5477-3e9c-403b-a566-59a376822f6b", "text": "A makett készítése során a stabil szerkezet kialakítása a cél.", "type": "true-false", "options": [{"id": "a0200587-9595-4d2d-94c1-af7b0e967506", "text": "Igaz", "isCorrect": true}, {"id": "bfab3839-7e5a-46e9-9ef8-3e3cb62682cb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5062a770-95e0-47b0-b74c-e494da4899d2", "text": "Mennyi a 2 cm élű kockákból álló 2x2x2-es házikó térfogata? (8 * 8 cm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "0fecc9b8-f83c-494a-940b-49c448b5ee54", "text": "A projektmunka kreatív megoldásokat ösztönöz.", "type": "true-false", "options": [{"id": "3bc0816e-9a63-4eaf-bdf0-38ea199613a2", "text": "Igaz", "isCorrect": true}, {"id": "b76b8b03-960d-4e3d-9277-3919d685b233", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8ac61968-7b17-474a-a934-359f5e7608bf", "text": "Hány éle van a kockának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('11e4ac2b-cbf8-4e0d-9198-b0b7286664cf', '21feff02-016d-46e2-bb9d-c27495133b1b', '113. óra: Projektóra III.', 'Az elkészített projektek és makettek bemutatása, csoportértékelés.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "6ba6f926-c91e-422d-91c7-dddb9ae2ad87", "text": "Mi a projekt bemutatásának legfőbb értéke?", "type": "multiple-choice", "options": [{"id": "96e00d81-4425-4f4c-aade-f01882108f62", "text": "Az elvégzett munka, a mérések, számítások és az elkészült makett ismertetése", "isCorrect": true}, {"id": "30cdf133-2ea2-4ee7-a6bc-b56ddf216c62", "text": "Gyors befejezés elnémulva", "isCorrect": false}, {"id": "b881725d-9d9c-41a6-95ab-2c910dab913b", "text": "Más csoportok munkájának elrejtése", "isCorrect": false}, {"id": "91ace38f-6bc5-43db-b326-a2613a4560a0", "text": "Csak a színek felsorolása", "isCorrect": false}], "timeLimit": 15}, {"id": "fc70c890-e02a-4620-a494-56acbebc81b7", "text": "A prezentációs készség és a szaknyelv használata fontos részét képezi az értékelésnek.", "type": "true-false", "options": [{"id": "9cf8f95e-8c73-4e31-9f99-c989cac16d91", "text": "Igaz", "isCorrect": true}, {"id": "3eff7899-36f8-4e23-92a8-67bb452cf5ab", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "65e615ee-06be-4938-b539-175fba9c36fc", "text": "Az önértékelés és a társak építő kritikája segít a fejlődésben.", "type": "true-false", "options": [{"id": "beadbc08-ca6d-4f8a-b597-62bd5996757d", "text": "Igaz", "isCorrect": true}, {"id": "8617007f-de56-428d-a987-78bbd5add52c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8da0bfe0-61be-4016-acea-7db4cb073017", "text": "Mennyi a 10 cm x 10 cm x 10 cm-es kockamakett térfogata literekben? (1000 cm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "a21516b1-efb5-49c8-b83b-97fd3200048d", "text": "A projektmunka során a csoport minden tagjának részfeladatot kell vállalnia.", "type": "true-false", "options": [{"id": "e6874bbf-51a7-4192-ba2c-90dbc65afe2d", "text": "Igaz", "isCorrect": true}, {"id": "da8ad470-d86f-4c92-8644-ea4495adc651", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "72c53a10-aca0-4b3a-957c-c904950648b5", "text": "A térszemlélet fejlesztése elengedhetetlen a 3D-s tervezéshez.", "type": "true-false", "options": [{"id": "73bae701-a9b9-425f-8e90-69d93bbbd083", "text": "Igaz", "isCorrect": true}, {"id": "ac12130c-d620-4348-b3f3-52dc6e071ca4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "085462bc-fb62-4067-ad5f-a794603bfd9c", "text": "Mennyi 1 m³ dm³-ben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('cf738687-8702-4bab-bc73-dc36cef351c5', '21feff02-016d-46e2-bb9d-c27495133b1b', '114. óra: Összefoglalás', 'A Kerület, terület, felszín és térfogat fejezet összefoglalása.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "88e68598-ea8c-4a09-b655-9f9361db7a2e", "text": "Mennyi a 5 cm és 6 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "4f150347-6358-495e-be8a-a97998a33c57", "text": "Mennyi a 5 cm és 6 cm oldalú téglalap kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "22"}, {"id": "cc86d010-e3c6-49b8-97a8-83a2e3744b76", "text": "Mennyi a 3 cm élű kocka felszíne? (6 * 9)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "54"}, {"id": "08bdbaaf-93ee-476d-8103-d6e478734adc", "text": "Mennyi a 3 cm élű kocka térfogata? (3 * 3 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "27"}, {"id": "8aa97e4c-4281-4240-be6c-2348d168c6bc", "text": "1 liter víz térfogata 1 dm³.", "type": "true-false", "options": [{"id": "d89c1f88-2189-4137-b377-ce403ab75aa8", "text": "Igaz", "isCorrect": true}, {"id": "536391b7-ee0f-4fbb-a005-69d97ca53a39", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f27e6b92-30bc-4e41-9fae-b0d03832cc76", "text": "Hány cm² 1 m²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10000"}, {"id": "181cada2-a9d5-4105-9340-5b28a4cb4856", "text": "A kerület 1D (hosszúság), a terület 2D, a térfogat 3D mennyiség.", "type": "true-false", "options": [{"id": "69effc97-3f4c-4c53-868a-e60aef87df30", "text": "Igaz", "isCorrect": true}, {"id": "f6978343-ef37-4ff8-a3f7-d797a2082c77", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f1419643-5c1c-4184-adae-01cddbd51b24', '21feff02-016d-46e2-bb9d-c27495133b1b', '115. óra: Gyakorlóóra', 'Gyakorló feladatsor önálló megoldása a mérések témakörben.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "3f85f4ca-2aad-44b3-af33-a4ded3f15d45", "text": "Mennyi a 8 cm és 4 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "32"}, {"id": "bcecb39e-5397-4d2c-9fee-968d7e34022f", "text": "Mennyi a 2 cm, 3 cm, 5 cm élű téglatest térfogata?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "ef4e78dd-f351-456b-89d5-d8544c8f0d9f", "text": "Mennyi a 2 cm, 3 cm, 5 cm élű téglatest felszíne? (2*(6+10+15) = 2*31)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "62"}, {"id": "42f45d87-74c3-4ceb-8c8b-b7ad67ab7cb3", "text": "A 1000 dm³ megegyezik 1 m³-rel.", "type": "true-false", "options": [{"id": "be96b865-dfa8-4e17-8593-dae47da85373", "text": "Igaz", "isCorrect": true}, {"id": "f299ea04-45e7-4096-b180-790f3cb0a39a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d1d43e34-e39f-4617-b4e5-8827b499c23f", "text": "Hány liter üdítő van egy 2500 cm³-es tartályban? (2,5 dm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2.5"}, {"id": "d9af94d2-edad-4822-a1b0-4b0ee442f2ee", "text": "A méréseknél az azonos mértékegységre való áttérés a sikeres számolás alapja.", "type": "true-false", "options": [{"id": "d21254c0-b789-4d1e-9973-2233440f3b05", "text": "Igaz", "isCorrect": true}, {"id": "e2cba6af-3abd-41b4-b8b4-2bc870b59efc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8c4e94ca-a24f-4f05-9cbc-c1f05a1c026d", "text": "Mennyi a 6 cm oldalú négyzet területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}]'::jsonb, true, NOW());